	headNorm(t.K, w.KNorm, c.HeadDim, c.NHeadKV*nTok, c.Eps)
	RoPEMulti(c, t.Q, pos, c.NHead, c.HeadDim, nTok)
	RoPEMulti(c, t.K, pos, c.NHeadKV, c.HeadDim, nTok)
