	t.IdxKPooled = make([]float32, nBlocks*c.IdxDim)
	inv := 1 / float32(c.Ratio)
	for b := 0; b < nBlocks; b++ {
		dst := t.IdxKPooled[b*c.IdxDim : (b+1)*c.IdxDim]
		for s := 0; s < c.Ratio; s++ {
			cell := 0 // the zero fill: a block that does not exist pools cell 0
			if b < nBid {
