func (g *PLEGPU) kvSlice(col, width int) []float32 {
	raw := g.abuf.ReadFloat32At(int(g.aKV), g.rows*g.kvN())
	out := make([]float32, g.rows*width)
	for t := 0; t < g.rows; t++ {
		copy(out[t*width:(t+1)*width], raw[t*g.kvN()+col:])
	}
	return out
