// its arenas cost.
func (g *PLEGPU) WeightBytes() int     { return g.wbuf.Size() + g.bank.Size() }
func (g *PLEGPU) ActivationBytes() int { return g.abuf.Size() + g.hbuf.Size() }

// Destroy releases every Vulkan object.
