		name string
		dst  *[]float32
	}{
		{"key", &w.Key}, {"value", &w.Value},
		{"norm_key", &w.NormKey}, {"norm_query", &w.NormQuery}, {"norm_conv", &w.NormConv},
		{"conv1d", &w.Conv1d},
	} {
		v, err := m.F32(p + t.name + ".weight")
		if err != nil {
			return w, err
		}
		*t.dst = v
	}
	return w, nil
