		d, err := tr.Get(name, nth)
		if err != nil {
			t.Fatal(err)
		}
		return d.Vals
	}
	switch {
	case layer == 0 && side == "attn":
		return get("hc_init", 0)
	case layer == 1 && side == "attn":
